<section class="card p-4 mt-4" id="registered-dealers">
<div class="d-flex flex-wrap justify-content-between align-items-start gap-3"><div><h2 class="h5 mb-1">Registered Dealers</h2><p class="text-muted mb-0">Read-only dealer directory synced separately for each mapped ERP agency. Dealer records do not grant login or property permissions.</p></div>
<?php if(can('agencies.edit')&&can('erp_sync.run')): ?><form method="post" action="<?= site_url('admin/agencies/'.$agency['id'].'/dealers/sync') ?>"><?= csrf_field() ?><input type="hidden" name="source" value="all"><button class="btn btn-primary" <?= empty(array_filter($dealerData['links'],static fn($l)=>$l['sync_eligible']))?'disabled':'' ?>>Sync All Mapped Sources</button></form><?php endif ?></div>
<?php if(!$dealerData['ready']): ?><div class="alert alert-warning mt-3 mb-0">Dealer tables are not available. Confirm the Phase 1 agency dealer SQL was applied to this portal database.</div>
<?php else: ?>
<div class="row g-3 mt-1">
<?php foreach(['SGC'=>'SGC Dealers','ZALMI'=>'Zalmi Dealers']as$code=>$label): $sourceLinks=array_values(array_filter($dealerData['links'],static fn($l)=>$l['source_code']===$code));$validLinks=array_values(array_filter($sourceLinks,static fn($l)=>$l['sync_eligible']));$count=array_sum(array_map(static fn($l)=>(int)$l['current_count'],$sourceLinks));$lastSuccess=null;$states=[];foreach($sourceLinks as$l){if(!empty($l['last_complete_at'])&&($lastSuccess===null||$l['last_complete_at']>$lastSuccess))$lastSuccess=$l['last_complete_at'];if(!empty($l['sync_status']))$states[]=$l['sync_status'];}$status=$states?implode(', ',array_unique($states)):'Not synced'; ?>
<div class="col-md-6"><div class="border rounded p-3 h-100"><div class="d-flex justify-content-between align-items-center gap-2"><h3 class="h6 mb-0"><?= esc($label) ?></h3><?php if(can('agencies.edit')&&can('erp_sync.run')&&$validLinks): ?><form method="post" action="<?= site_url('admin/agencies/'.$agency['id'].'/dealers/sync') ?>"><?= csrf_field() ?><input type="hidden" name="source" value="<?= esc($code,'attr') ?>"><button class="btn btn-sm btn-outline-primary">Sync <?= esc($code) ?></button></form><?php endif ?></div><div class="mt-2">Current memberships: <strong><?= $count ?></strong><br>Sync status: <strong><?= esc($status) ?></strong><br>Last successful complete sync: <strong><?= esc($lastSuccess??'Not yet synced') ?></strong></div><?php if(!$validLinks): ?><small class="text-muted d-block mt-2">No active authorized mapping for this source.</small><?php endif ?><?php foreach($sourceLinks as$l): if(!empty($l['error_summary'])): ?><small class="text-danger d-block mt-2"><?= esc($l['source_name']) ?> / agency #<?= esc($l['erp_agency_id']) ?>: <?= esc($l['error_summary']) ?></small><?php endif;endforeach ?></div></div>
<?php endforeach ?>
</div>
<form class="row g-2 align-items-end mt-3" method="get" action="<?= site_url('admin/agencies/'.$agency['id']) ?>"><input type="hidden" name="dealer_page" value="1"><div class="col-sm-3"><label class="form-label" for="dealer-source-filter">ERP source</label><select class="form-select" id="dealer-source-filter" name="dealer_source"><option value="all" <?= $dealerData['source']==='all'?'selected':'' ?>>All sources</option><option value="SGC" <?= $dealerData['source']==='SGC'?'selected':'' ?>>SGC</option><option value="ZALMI" <?= $dealerData['source']==='ZALMI'?'selected':'' ?>>Zalmi</option></select></div><div class="col-sm-6"><label class="form-label" for="dealer-search">Search dealer name or mobile</label><input class="form-control" id="dealer-search" name="dealer_q" maxlength="100" value="<?= esc($dealerData['q'],'attr') ?>"></div><div class="col-sm-3"><button class="btn btn-outline-secondary">Search</button></div></form>
<div class="table-responsive mt-3"><table class="table table-sm table-striped align-middle"><thead><tr><th>Dealer name</th><th>ERP source</th><th>ERP ledger ID</th><th>ERP agency ID</th><th>Mobile</th><th>Email</th><th>Locked</th><th>Staff-agent flag</th><th>Membership</th><th>Last seen</th></tr></thead><tbody>
<?php if(!$dealerData['rows']): ?><tr><td colspan="10" class="text-center text-muted py-4">No synced dealers match this agency and filter.</td></tr><?php endif ?>
<?php foreach($dealerData['rows']as$dealer): ?><tr><th scope="row"><?= esc($dealer['erp_name']) ?><?php if($dealer['membership_status']==='current'&&can('agencies.edit')): ?><a class="d-block small" href="<?= site_url('admin/dealer-logins/'.$dealer['membership_id']) ?>">Dealer login</a><?php endif ?><?php if($dealer['erp_staff_agent_flag']==='yes'): ?> <span class="badge text-bg-warning">Staff-agent overlap</span><?php endif ?></th><td><?= esc($dealer['source_name']) ?></td><td><?= esc($dealer['erp_ledger_id']) ?></td><td><?= esc($dealer['erp_agency_id']) ?></td><td><?= esc($dealer['erp_mobile']?:'Not provided') ?></td><td><?= esc($dealer['erp_email']?:'Not provided') ?></td><td><?= esc(ucfirst($dealer['erp_locked_flag'])) ?></td><td><?= esc($dealer['erp_staff_agent_flag']) ?></td><td><span class="badge <?= $dealer['membership_status']==='current'?'text-bg-success':'text-bg-secondary' ?>"><?= esc(ucfirst($dealer['membership_status'])) ?></span></td><td><?= esc($dealer['last_seen_at']) ?></td></tr><?php endforeach ?>
</tbody></table></div>
<?php $pages=max(1,(int)ceil($dealerData['total']/$dealerData['perPage']));if($pages>1): ?><nav aria-label="Dealer pages"><ul class="pagination pagination-sm"><li class="page-item <?= $dealerData['page']<=1?'disabled':'' ?>"><a class="page-link" href="<?= site_url('admin/agencies/'.$agency['id'].'?'.http_build_query(['dealer_source'=>$dealerData['source'],'dealer_q'=>$dealerData['q'],'dealer_page'=>max(1,$dealerData['page']-1)])) ?>">Previous</a></li><li class="page-item disabled"><span class="page-link">Page <?= $dealerData['page'] ?> of <?= $pages ?></span></li><li class="page-item <?= $dealerData['page']>=$pages?'disabled':'' ?>"><a class="page-link" href="<?= site_url('admin/agencies/'.$agency['id'].'?'.http_build_query(['dealer_source'=>$dealerData['source'],'dealer_q'=>$dealerData['q'],'dealer_page'=>min($pages,$dealerData['page']+1)])) ?>">Next</a></li></ul></nav><?php endif ?>
<?php endif ?></section>
